"""Provides functionality for casting data to the types defined in a validation schema."""
from datetime import datetime
from typing import Any

import pandas as pd


def cast_to_schema(data: dict[str, pd.DataFrame], schema: dict) -> None:
    """
    Cast the values in a workbook to the data types specified in the schema. This
    process modifies workbook in-place.

    Casting is performed on a cell-by-cell basis, converting each value from the type
    it was extracted as (often a string) to the native Python type specified by the
    schema.

    This step is needed because data extracted from spreadsheets are often parsed as
    strings by default.

    :param data: A dictionary mapping table names to DataFrames.
    :param schema: A dictionary specifying the data types for each column in each table.
    :return: None
    """
    for table, table_data in data.items():
        if table not in schema:
            continue  # skip casting if schema doesn't exist for that table - this will be caught during validation

        column_to_type = schema[table]["columns"]

        for column, target_type in column_to_type.items():
            if column in table_data.columns:
                table_data[column] = table_data[column].map(lambda value: _cast_value(value, target_type))


def _cast_value(value: Any, target_type: type) -> Any:
    """Cast a single cell value to the target type, or leave it unchanged if it cannot be cast.

    :param value: the value to cast
    :param target_type: the type to cast the value to
    :return: the cast value
    """
    if value is None or (not isinstance(value, list) and pd.isna(value)):
        return value

    if isinstance(value, target_type):
        return value

    try:
        if target_type is datetime:
            return pd.to_datetime(value)
        if target_type is float:
            return float(value)
        if target_type is int:
            return int(value)
        if target_type is bool:
            return bool(value)
        if target_type is str:
            return str(value)
    except (ValueError, TypeError):
        return value

    return value

